package com.formation.loan.exception; import feign.FeignException; import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestControllerAdvice public class GlobalExceptionHandler { @ExceptionHandler(LoanNotFoundException.class) ResponseEntity<ApiError> nf(LoanNotFoundException e){return r(404,e.getMessage());} @ExceptionHandler(LoanException.class) ResponseEntity<ApiError> le(LoanException e){return r(e.getStatus(),e.getMessage());} @ExceptionHandler(FeignException.class) ResponseEntity<ApiError> fe(FeignException e){int s=e.status()==404?400:e.status()==409?409:503;String m=s==400?"Le livre demandé n'existe pas":s==409?"Aucun exemplaire disponible pour ce livre":"book-service est indisponible";return r(s,m);} @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<ApiError> val(MethodArgumentNotValidException e){Map<String,String> f=new LinkedHashMap<>();e.getBindingResult().getFieldErrors().forEach(x->f.putIfAbsent(x.getField(),x.getDefaultMessage()));return ResponseEntity.badRequest().body(new ApiError(400,"Bad Request","La requête contient des données invalides",f));} private ResponseEntity<ApiError> r(int s,String m){HttpStatus h=HttpStatus.valueOf(s);return ResponseEntity.status(h).body(new ApiError(s,h.getReasonPhrase(),m));}}
